insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('C1', 'cribado', 1, null, 1, 'Atención al nombre y al señalamiento', array['familia','fisico']::text[], false, false, 'Cuando le llaman por su nombre o le señalan algo, ¿mira a la persona o a lo señalado?', null, null, 'Sí', 'A veces', 'No', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('C2', 'cribado', 1, null, 2, 'Peticiones espontáneas', array['familia','fisico']::text[], false, false, '¿Pide al menos 5 cosas distintas con palabras, signos o pictogramas, sin que se le pregunte?', null, null, 'Sí', 'A veces', 'No', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('C3', 'cribado', 1, null, 3, 'Imitación e igualación', array['familia','fisico']::text[], false, false, '¿Imita acciones nuevas cuando se le dice "Haz lo mismo" y empareja imágenes iguales?', null, null, 'Sí', 'A veces', 'No', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('C4', 'cribado', 2, null, 4, 'Vocabulario', array['familia','fisico']::text[], false, false, '¿Señala y nombra al menos 10 objetos cotidianos?', null, null, 'Sí', 'A veces', 'No', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('C5', 'cribado', 2, null, 5, 'Preguntas sobre lo ausente', array['familia','fisico']::text[], false, false, '¿Responde a "¿para qué sirve…?", "¿dónde…?" o "¿quién…?" sobre cosas que no están delante?', null, null, 'Sí', 'A veces', 'No', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('C6', 'cribado', 3, null, 6, 'Marcos relacionales', array['familia','fisico']::text[], false, false, '¿Entiende y usa "lo contrario de", "más grande que", "antes de" o "si… entonces"?', null, null, 'Sí', 'A veces', 'No', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('C7', 'cribado', 4, null, 7, 'Toma de perspectiva', array['familia','fisico']::text[], false, false, '¿Se da cuenta de que otra persona puede ver, saber o querer algo distinto que él?', null, null, 'Sí', 'A veces', 'No', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.1-1', 'item', 1, (select id from dominios_curriculo where codigo = '1.1'), 1, 'Responde a su nombre', array['fisico']::text[], false, false, 'Mientras el alumno juega, el evaluador dice su nombre una vez, con tono normal, a 1-2 m y fuera de su campo visual. Espera 3 s. 5 oportunidades separadas al menos 30 s.', 'Un juguete de interés moderado.', 5, 'Mira al evaluador en 3 s o menos en 4-5 de 5 oportunidades', 'En 2-3 de 5, o solo si se repite el nombre o se acerca el evaluador', '0-1 de 5', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.1-2', 'item', 1, (select id from dominios_curriculo where codigo = '1.1'), 2, 'Sigue un señalamiento', array['fisico']::text[], false, false, 'El evaluador dice "¡Mira!" y señala uno de los objetos, sin mirarlo antes. 5 ensayos con objetos distintos.', '5 objetos llamativos colocados a unos 2 m.', 5, 'Dirige la mirada al objeto señalado en 4-5 de 5', 'En 2-3 de 5, o con ayuda', '0-1 de 5', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.1-3', 'item', 1, (select id from dominios_curriculo where codigo = '1.1'), 3, 'Permanece sentado en una tarea', array['fisico','familia']::text[], false, false, '"Vamos a hacer esto". Se cronometra el tiempo que permanece sentado trabajando.', 'Tarea de mesa adecuada a su nivel (encajable, puzle).', null, '3 minutos sin levantarse', 'Entre 1 y 3 minutos, o con redirecciones', 'Menos de 1 minuto', '¿Puede estar sentado unos minutos haciendo una actividad en la mesa?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.1-4', 'item', 1, (select id from dominios_curriculo where codigo = '1.1'), 4, 'Espera', array['fisico','familia']::text[], false, false, 'Se pone el preferido delante y se dice "Espera"; se cuentan 10 s (3 ensayos). Después, 2 turnos en el juego.', 'Un preferido y un juego de turnos (ej. torre de bloques).', 5, 'Espera en los 3 ensayos y respeta los 2 turnos', 'Lo consigue en algunos', 'En ninguno', '¿Puede esperar unos segundos sin coger algo que quiere? ¿Y respetar turnos en un juego?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.2-1', 'item', 1, (select id from dominios_curriculo where codigo = '1.2'), 1, 'Pide lo que quiere', array['fisico','familia']::text[], false, false, '10 minutos de juego libre en los que el evaluador no pregunta "¿qué quieres?". Se registra cada petición espontánea, en cualquier modalidad (palabra, signo o pictograma). Puede hacerse al inicio de la sesión, mientras el alumno se adapta a la sala.', '6-8 preferidos a la vista pero fuera de su alcance.', null, '5 o más peticiones distintas sin ayuda', '2-4 peticiones, o solo con modelo', '0-1 peticiones', '¿Pide al menos 5 cosas distintas por su cuenta, con palabras, signos o pictogramas?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.2-2', 'item', 1, (select id from dominios_curriculo where codigo = '1.2'), 2, 'Elige entre opciones', array['fisico']::text[], false, false, 'Se presentan en fila y se pregunta "¿Cuál quieres?". 5 ensayos cambiando el orden.', '3 preferidos.', 5, 'Elige uno de forma clara (señala o coge) en 4-5 de 5', 'En 2-3 de 5, o con ayuda', '0-1 de 5', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.2-3', 'item', 1, (select id from dominios_curriculo where codigo = '1.2'), 3, 'Pide ayuda o lo que falta', array['fisico']::text[], false, false, 'Se le da el material y se esperan 10 s sin intervenir. 4 oportunidades (2 de cada tipo).', 'Bote transparente bien cerrado con un preferido dentro; puzle al que le falta una pieza.', 4, 'Pide ayuda o el objeto que falta en 3-4 oportunidades', 'En 1-2, o solo con modelo', 'En ninguna', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.2-4', 'item', 1, (select id from dominios_curriculo where codigo = '1.2'), 4, 'Rechaza y pide permiso', array['fisico','familia']::text[], false, false, 'Se le ofrece lo que no le gusta (2 veces) y se deja a su alcance el objeto del evaluador (2 veces).', 'Un objeto o alimento que no le gusta; un objeto del evaluador.', 4, 'Rechaza de forma adecuada ("No quiero") y pide permiso en 3-4 ocasiones, sin conducta problema', 'En 1-2 ocasiones', 'En ninguna', '¿Dice que no de forma adecuada? ¿Pide permiso antes de coger algo de otros?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.2-5', 'item', 1, (select id from dominios_curriculo where codigo = '1.2'), 5, 'Acepta un "no" y tolera lo necesario', array['familia']::text[], false, false, 'Se pregunta a la familia (no se observa en sesión).', null, null, 'Casi siempre', 'A veces', 'Casi nunca', 'Cuando le dicen "no" o "ahora no", ¿lo acepta sin rabietas? ¿Tolera el cepillado de dientes, cortarse el pelo o ir al médico?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.3-1', 'item', 1, (select id from dominios_curriculo where codigo = '1.3'), 1, 'Imitación motora generalizada', array['fisico']::text[], false, false, '"Haz lo mismo" con 5 acciones: 3 habituales (aplaudir, levantar los brazos, tocarse la cabeza) y 2 nuevas que no aparecen en los programas (tocarse la oreja con el codo, girar las muñecas).', null, 5, '4-5 acciones, incluidas las 2 nuevas', 'Solo las habituales, o con ayuda', '0-1 acciones', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.3-2', 'item', 1, (select id from dominios_curriculo where codigo = '1.3'), 2, 'Imitación vocal', array['fisico']::text[], false, false, '"Di lo mismo" con 3 sílabas (ma, pe, to) y 2 palabras (agua, pelota). Se aceptan aproximaciones articulatorias claras.', null, 5, '4-5 de 5 sin ayuda', '2-3 de 5, o con ayuda', '0-1 de 5', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.3-3', 'item', 1, (select id from dominios_curriculo where codigo = '1.3'), 3, 'Igualación de imágenes', array['tableta']::text[], false, false, 'En pantalla, un modelo y 3 comparaciones: "Pon con el igual". 5 ensayos con imágenes distintas, sin repetir la posición de la correcta.', null, 5, '4-5 de 5 ensayos correctos sin ayuda', '2-3 de 5, o solo con ayuda', '0-1 de 5', null, null, true, '[{"consigna": "Pon con el igual", "fase": "test", "modelo": {"e": "🍎"}, "opciones": [{"e": "🍎"}, {"e": "🐟"}, {"e": "⚽"}]}, {"consigna": "Pon con el igual", "fase": "test", "modelo": {"e": "🌂"}, "opciones": [{"e": "🌂"}, {"e": "🔑"}, {"e": "🐢"}]}, {"consigna": "Pon con el igual", "fase": "test", "modelo": {"e": "🎈"}, "opciones": [{"e": "🎈"}, {"e": "🦆"}, {"e": "🕯️"}]}, {"consigna": "Pon con el igual", "fase": "test", "modelo": {"e": "🦒"}, "opciones": [{"e": "🦒"}, {"e": "🪑"}, {"e": "🍇"}]}, {"consigna": "Pon con el igual", "fase": "test", "modelo": {"e": "🚲"}, "opciones": [{"e": "🚲"}, {"e": "🌻"}, {"e": "🧦"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.3-4', 'item', 1, (select id from dominios_curriculo where codigo = '1.3'), 4, 'Igualación no visual', array['fisico']::text[], false, false, '"Pon con el igual". 3 ensayos.', '3 pares de botes sonoros (arroz, canicas, arena) o, si hay sensibilidad al sonido, 3 pares de texturas en una bolsa opaca.', 3, '3 de 3', '2 de 3', '0-1 de 3', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.3-5', 'item', 1, (select id from dominios_curriculo where codigo = '1.3'), 5, 'Copia gráfica', array['fisico']::text[], false, false, '"Hazlo igual" con 3 trazos (línea vertical, círculo, cruz) y 2 letras (O, A) dibujados por el evaluador.', 'Papel y lápiz.', 5, '4-5 copias reconocibles sin ayuda', '2-3, o con ayuda', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.4-1', 'item', 1, (select id from dominios_curriculo where codigo = '1.4'), 1, 'Completa canciones y frases', array['fisico']::text[], false, false, 'Se empiezan 3 canciones o frases conocidas por la familia y se hace una pausa antes de la última palabra (ej. "Cumpleaños…"). Antes se pregunta a la familia qué canciones conoce.', null, 3, '3 de 3', '1-2', 'Ninguna', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.4-2', 'item', 1, (select id from dominios_curriculo where codigo = '1.4'), 2, 'Información personal', array['fisico']::text[], false, false, '"¿Cómo te llamas?", "¿Cuántos años tienes?", "¿Cómo se llama tu mamá / papá?".', null, 3, '3 de 3', '1-2', 'Ninguna', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.4-3', 'item', 1, (select id from dominios_curriculo where codigo = '1.4'), 3, 'Cuenta objetos', array['fisico']::text[], false, false, '"Cuenta". 2 ensayos: con 3 cubos y con 5.', '5 cubos iguales en fila.', 2, 'Cuenta los dos conjuntos tocando cada objeto una sola vez y en el orden correcto', 'La serie es correcta pero la correspondencia no, o al revés', 'Ninguna de las dos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-1.4-4', 'item', 1, (select id from dominios_curriculo where codigo = '1.4'), 4, 'Responde sí o no', array['fisico']::text[], false, false, '"¿Quieres ___?" con cada uno, en orden aleatorio.', '2 objetos preferidos y 2 que no le gustan.', 4, '4 de 4 coherentes con sus preferencias', '2-3', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.1-1', 'item', 2, (select id from dominios_curriculo where codigo = '2.1'), 1, 'Vocabulario receptivo', array['tableta']::text[], false, false, '"Toca ___", con 4 imágenes en pantalla. 10 ensayos.', '10 imágenes, 2 por categoría: plátano y pan, vaca y cerdo, coche y avión, zapatos y camiseta, cuchara y vaso.', 10, '9-10 de 10', '6-8', '5 o menos', null, null, true, '[{"consigna": "Toca el plátano", "fase": "test", "opciones": [{"e": "🍌"}, {"e": "🐄"}, {"e": "✈️"}, {"e": "👕"}]}, {"consigna": "Toca el pan", "fase": "test", "opciones": [{"e": "🍞"}, {"e": "✈️"}, {"e": "🥄"}, {"e": "🐄"}]}, {"consigna": "Toca la vaca", "fase": "test", "opciones": [{"e": "🐄"}, {"e": "🥄"}, {"e": "🍞"}, {"e": "✈️"}]}, {"consigna": "Toca el cerdo", "fase": "test", "opciones": [{"e": "🐖"}, {"e": "🍞"}, {"e": "👟"}, {"e": "🥄"}]}, {"consigna": "Toca el coche", "fase": "test", "opciones": [{"e": "🚗"}, {"e": "👟"}, {"e": "🥛"}, {"e": "🍞"}]}, {"consigna": "Toca el avión", "fase": "test", "opciones": [{"e": "✈️"}, {"e": "🥛"}, {"e": "🐄"}, {"e": "👟"}]}, {"consigna": "Toca el zapato", "fase": "test", "opciones": [{"e": "👟"}, {"e": "🐄"}, {"e": "✈️"}, {"e": "🥛"}]}, {"consigna": "Toca la camiseta", "fase": "test", "opciones": [{"e": "👕"}, {"e": "✈️"}, {"e": "🍌"}, {"e": "🐄"}]}, {"consigna": "Toca la cuchara", "fase": "test", "opciones": [{"e": "🥄"}, {"e": "🍌"}, {"e": "🐖"}, {"e": "✈️"}]}, {"consigna": "Toca el vaso", "fase": "test", "opciones": [{"e": "🥛"}, {"e": "🐖"}, {"e": "👟"}, {"e": "🍌"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.1-2', 'item', 2, (select id from dominios_curriculo where codigo = '2.1'), 2, 'Vocabulario expresivo', array['fisico']::text[], false, false, '"¿Qué es?" con cada imagen, de una en una.', 'Las mismas 10 imágenes de EV-2.1-1.', 10, '9-10 de 10', '6-8', '5 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.1-3', 'item', 2, (select id from dominios_curriculo where codigo = '2.1'), 3, 'Vinculación mutua con estímulos nuevos', array['tableta']::text[], true, true, 'Entrenamiento: bloques de 6 ensayos con refuerzo y corrección hasta 5 de 6 en un bloque (máximo 3 bloques o 5 minutos); si no se alcanza, puntuación 0 y no se aplica el test. Test: 6 ensayos sin ayudas ni refuerzo diferencial (solo refuerzo general por colaborar). Se entrena nombre → objeto ("Toca el ZAP", 3 opciones) y se prueba objeto → nombre ("¿Cómo se llama esto?", sin opciones). Variante sin lenguaje vocal: se entrena objeto → símbolo y se prueba símbolo → objeto, ambos por selección en pantalla.', '3 dibujos de objetos inventados con nombres inventados (ZAP, MELO, TIRO), exclusivos de la evaluación.', 6, '5-6 de 6 en el test', '4 de 6 en el test', '3 o menos, o no alcanza el criterio de entrenamiento', null, null, true, '[{"consigna": "Toca el ZAP", "fase": "entrenamiento", "opciones": [{"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "vocal"}, {"consigna": "Toca el MELO", "fase": "entrenamiento", "opciones": [{"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "vocal"}, {"consigna": "Toca el TIRO", "fase": "entrenamiento", "opciones": [{"fig": "objeto", "s": "EV-2.1-3:TIRO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}], "variante": "vocal"}, {"consigna": "Toca el MELO", "fase": "entrenamiento", "opciones": [{"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "vocal"}, {"consigna": "Toca el TIRO", "fase": "entrenamiento", "opciones": [{"fig": "objeto", "s": "EV-2.1-3:TIRO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}], "variante": "vocal"}, {"consigna": "Toca el ZAP", "fase": "entrenamiento", "opciones": [{"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "vocal"}, {"consigna": "¿Cómo se llama esto?", "fase": "test", "modelo": {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, "variante": "vocal"}, {"consigna": "¿Cómo se llama esto?", "fase": "test", "modelo": {"fig": "objeto", "s": "EV-2.1-3:MELO"}, "variante": "vocal"}, {"consigna": "¿Cómo se llama esto?", "fase": "test", "modelo": {"fig": "objeto", "s": "EV-2.1-3:TIRO"}, "variante": "vocal"}, {"consigna": "¿Cómo se llama esto?", "fase": "test", "modelo": {"fig": "objeto", "s": "EV-2.1-3:MELO"}, "variante": "vocal"}, {"consigna": "¿Cómo se llama esto?", "fase": "test", "modelo": {"fig": "objeto", "s": "EV-2.1-3:TIRO"}, "variante": "vocal"}, {"consigna": "¿Cómo se llama esto?", "fase": "test", "modelo": {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, "variante": "vocal"}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, "opciones": [{"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, {"fig": "simbolo", "s": "EV-2.1-3:MELO"}, {"fig": "simbolo", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "objeto", "s": "EV-2.1-3:MELO"}, "opciones": [{"fig": "simbolo", "s": "EV-2.1-3:MELO"}, {"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, {"fig": "simbolo", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "objeto", "s": "EV-2.1-3:TIRO"}, "opciones": [{"fig": "simbolo", "s": "EV-2.1-3:TIRO"}, {"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, {"fig": "simbolo", "s": "EV-2.1-3:MELO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "objeto", "s": "EV-2.1-3:MELO"}, "opciones": [{"fig": "simbolo", "s": "EV-2.1-3:MELO"}, {"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, {"fig": "simbolo", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "objeto", "s": "EV-2.1-3:TIRO"}, "opciones": [{"fig": "simbolo", "s": "EV-2.1-3:TIRO"}, {"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, {"fig": "simbolo", "s": "EV-2.1-3:MELO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, "opciones": [{"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, {"fig": "simbolo", "s": "EV-2.1-3:MELO"}, {"fig": "simbolo", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, "opciones": [{"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.1-3:MELO"}, "opciones": [{"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.1-3:TIRO"}, "opciones": [{"fig": "objeto", "s": "EV-2.1-3:TIRO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.1-3:MELO"}, "opciones": [{"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.1-3:TIRO"}, "opciones": [{"fig": "objeto", "s": "EV-2.1-3:TIRO"}, {"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}], "variante": "no_vocal"}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.1-3:ZAP"}, "opciones": [{"fig": "objeto", "s": "EV-2.1-3:ZAP"}, {"fig": "objeto", "s": "EV-2.1-3:MELO"}, {"fig": "objeto", "s": "EV-2.1-3:TIRO"}], "variante": "no_vocal"}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.1-4', 'item', 2, (select id from dominios_curriculo where codigo = '2.1'), 4, 'Acciones', array['fisico']::text[], false, false, '4 instrucciones sin modelo ("Aplaude", "Salta", "Siéntate", "Toca la mesa y da una vuelta") y 2 ensayos de "¿Qué estoy haciendo?" mientras el evaluador hace una acción.', null, 6, '5-6 de 6', '3-4', '0-2', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.1-5', 'item', 2, (select id from dominios_curriculo where codigo = '2.1'), 5, 'Categorías abstractas', array['tableta','fisico']::text[], false, false, 'Para cada categoría (colores, emociones, letras y números), un ensayo receptivo en pantalla ("Toca el rojo") y otro expresivo ("¿Qué letra es?"). 8 ensayos.', null, 8, '7-8 de 8', '4-6', '3 o menos', null, null, true, '[{"consigna": "Toca el rojo", "fase": "test", "opciones": [{"color": "#DC2626"}, {"color": "#2563EB"}, {"color": "#16A34A"}, {"color": "#FACC15"}]}, {"consigna": "Toca la cara contenta", "fase": "test", "opciones": [{"e": "😀"}, {"e": "😢"}, {"e": "😠"}, {"e": "😨"}]}, {"consigna": "Toca la S", "fase": "test", "opciones": [{"t": "S"}, {"t": "L"}, {"t": "P"}, {"t": "T"}]}, {"consigna": "Toca el 7", "fase": "test", "opciones": [{"t": "7"}, {"t": "3"}, {"t": "5"}, {"t": "9"}]}, {"consigna": "¿Qué color es?", "fase": "test", "modelo": {"color": "#2563EB"}}, {"consigna": "¿Cómo está?", "fase": "test", "modelo": {"e": "😢"}}, {"consigna": "¿Qué letra es?", "fase": "test", "modelo": {"t": "M"}}, {"consigna": "¿Qué número es?", "fase": "test", "modelo": {"t": "4"}}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.2-1', 'item', 2, (select id from dominios_curriculo where codigo = '2.2'), 1, 'Combinatoria con estímulos nuevos', array['tableta']::text[], true, true, 'Entrenamiento: bloques de 6 ensayos con refuerzo y corrección hasta 5 de 6 en un bloque (máximo 3 bloques o 5 minutos); si no se alcanza, puntuación 0 y no se aplica el test. Test: 6 ensayos sin ayudas ni refuerzo diferencial (solo refuerzo general por colaborar). Se entrena A → B ("Toca el BIM") y B → C (dibujo como modelo, se elige el símbolo). Test: A → C ("Toca el BIM" con símbolos) y C → A ("¿Cómo se llama?"); sin lenguaje vocal, solo A → C. Las clases formadas se guardan para EV-4.2-3.', '3 clases exclusivas de la evaluación: A nombres inventados dichos (BIM, LOFA, TUR), B dibujos de criaturas inventadas, C símbolos abstractos.', 6, '5-6 de 6 en el test', '4 de 6 en el test', '3 o menos, o no alcanza el criterio de entrenamiento', null, null, true, '[{"consigna": "Toca el BIM", "fase": "entrenamiento", "opciones": [{"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "criatura", "s": "EV-2.2-1:TUR"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "criatura", "s": "EV-2.2-1:LOFA"}, "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, {"consigna": "Toca el TUR", "fase": "entrenamiento", "opciones": [{"fig": "criatura", "s": "EV-2.2-1:TUR"}, {"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "criatura", "s": "EV-2.2-1:LOFA"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "criatura", "s": "EV-2.2-1:BIM"}, "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, {"consigna": "Toca el LOFA", "fase": "entrenamiento", "opciones": [{"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "criatura", "s": "EV-2.2-1:TUR"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "criatura", "s": "EV-2.2-1:TUR"}, "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}, {"consigna": "Toca el BIM", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}], "variante": "vocal"}, {"consigna": "Toca el LOFA", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}], "variante": "vocal"}, {"consigna": "Toca el TUR", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}], "variante": "vocal"}, {"consigna": "¿Cómo se llama?", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, "variante": "vocal"}, {"consigna": "¿Cómo se llama?", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.2-1:TUR"}, "variante": "vocal"}, {"consigna": "¿Cómo se llama?", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, "variante": "vocal"}, {"consigna": "Toca el BIM", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}], "variante": "no_vocal"}, {"consigna": "Toca el LOFA", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}], "variante": "no_vocal"}, {"consigna": "Toca el TUR", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}], "variante": "no_vocal"}, {"consigna": "Toca el LOFA", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}], "variante": "no_vocal"}, {"consigna": "Toca el TUR", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}], "variante": "no_vocal"}, {"consigna": "Toca el BIM", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}], "variante": "no_vocal"}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.2-2', 'item', 2, (select id from dominios_curriculo where codigo = '2.2'), 2, 'Dictado', array['fisico']::text[], false, false, '"Escribe ___", sin modelo: letras A y M, sílabas MA y PE, palabra SOPA.', 'Papel y lápiz.', 5, '4-5 de 5', '2-3', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.2-3', 'item', 2, (select id from dominios_curriculo where codigo = '2.2'), 3, 'Lectura con comprensión', array['tableta']::text[], false, false, 'Aparece una oración impresa ("El perro come", "Mamá duerme", "El gato bebe") y 3 imágenes debajo (pares mínimos: cada distractor cambia una sola palabra): "Lee y toca el dibujo".', null, 3, '3 de 3', '2', '0-1', null, null, true, '[{"consigna": "Lee y toca el dibujo", "fase": "test", "modelo": {"t": "El perro come"}, "opciones": [{"e": "🐕🍖"}, {"e": "🐕💤"}, {"e": "👦🍖"}]}, {"consigna": "Lee y toca el dibujo", "fase": "test", "modelo": {"t": "Mamá duerme"}, "opciones": [{"e": "👩💤"}, {"e": "👩🍖"}, {"e": "🐕💤"}]}, {"consigna": "Lee y toca el dibujo", "fase": "test", "modelo": {"t": "El gato bebe"}, "opciones": [{"e": "🐈🥛"}, {"e": "🐈💤"}, {"e": "🐕🥛"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.2-4', 'item', 2, (select id from dominios_curriculo where codigo = '2.2'), 4, 'Cardinalidad', array['fisico']::text[], false, false, '"Dame tres" y "Dame cinco" de un montón de 10 cubos; "¿Cuántos hay?" con conjuntos de 2 y de 4.', '10 cubos iguales.', 4, '4 de 4', '2-3', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.2-5', 'item', 2, (select id from dominios_curriculo where codigo = '2.2'), 5, 'Preguntas sobre algo ausente (1)', array['fisico']::text[], false, false, 'Sin objetos delante: "¿De qué color es el plátano? ¿Y la fresa?", "¿Para qué sirven las tijeras? ¿Y el vaso?".', null, 4, '4 de 4', '2-3', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.2-6', 'item', 2, (select id from dominios_curriculo where codigo = '2.2'), 6, 'Preguntas sobre algo ausente (2)', array['fisico']::text[], false, false, '"¿Quién apaga el fuego?", "¿Dónde dormimos?", "¿Cuándo vamos a la playa?", "¿Cómo viajamos por el mar?". Se acepta cualquier respuesta válida.', null, 4, '4 de 4', '2-3', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.3-1', 'item', 2, (select id from dominios_curriculo where codigo = '2.3'), 1, 'Transformación mutua', array['tableta']::text[], true, false, 'Entrenamiento: bloques de 6 ensayos con refuerzo y corrección hasta 5 de 6 en un bloque (máximo 3 bloques o 5 minutos); si no se alcanza, puntuación 0 y no se aplica el test. Test: 6 ensayos sin ayudas ni refuerzo diferencial (solo refuerzo general por colaborar). Se entrena A → B (objeto como modelo, se elige el símbolo). Test: 3 ensayos B → A (mutuo) y 3 de transformación solo con los símbolos y el distractor ("¿Cuál sirve para viajar?", "¿Cuál sirve para jugar?", "¿Cuál sale de día?").', 'Coche, pelota y sol (A); 3 símbolos exclusivos de la evaluación (B) y un símbolo distractor.', 6, '5-6 de 6, con los 3 de transformación correctos', '4 de 6, o solo los mutuos', '3 o menos, o no alcanza el criterio de entrenamiento', null, null, true, '[{"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"e": "🚗"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:pelota"}, {"fig": "simbolo", "s": "EV-2.3-1:sol"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"e": "⚽"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:pelota"}, {"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:sol"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"e": "☀️"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:sol"}, {"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:pelota"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"e": "⚽"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:pelota"}, {"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:sol"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"e": "☀️"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:sol"}, {"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:pelota"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"e": "🚗"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:pelota"}, {"fig": "simbolo", "s": "EV-2.3-1:sol"}]}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:coche"}, "opciones": [{"e": "🚗"}, {"e": "⚽"}, {"e": "☀️"}]}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:pelota"}, "opciones": [{"e": "⚽"}, {"e": "🚗"}, {"e": "☀️"}]}, {"consigna": "Pon con el que va", "fase": "test", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:sol"}, "opciones": [{"e": "☀️"}, {"e": "🚗"}, {"e": "⚽"}]}, {"consigna": "¿Cuál sirve para viajar?", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:pelota"}, {"fig": "simbolo", "s": "EV-2.3-1:sol"}, {"fig": "simbolo", "s": "EV-2.3-1:distractor"}]}, {"consigna": "¿Cuál sirve para jugar?", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:pelota"}, {"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:sol"}, {"fig": "simbolo", "s": "EV-2.3-1:distractor"}]}, {"consigna": "¿Cuál sale de día?", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.3-1:sol"}, {"fig": "simbolo", "s": "EV-2.3-1:coche"}, {"fig": "simbolo", "s": "EV-2.3-1:pelota"}, {"fig": "simbolo", "s": "EV-2.3-1:distractor"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.3-2', 'item', 2, (select id from dominios_curriculo where codigo = '2.3'), 2, 'Función apetitiva', array['tableta']::text[], true, false, 'Entrenamiento: bloques de 6 ensayos con refuerzo y corrección hasta 5 de 6 en un bloque (máximo 3 bloques o 5 minutos); si no se alcanza, puntuación 0 y no se aplica el test. Test: 6 ensayos sin ayudas ni refuerzo diferencial (solo refuerzo general por colaborar). Se entrena preferido → símbolo 1 y objeto neutro → símbolo 2. Test: "¿Cuál quieres?" con los dos símbolos y el distractor, 4 ensayos, sin entregar nada.', 'Un preferido del alumno, un objeto neutro, 2 símbolos exclusivos de la evaluación y un distractor.', 4, 'Elige el símbolo del preferido 4 de 4 veces', '3 de 4', '2 o menos, o no alcanza el criterio de entrenamiento', null, null, true, '[{"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"externo": "El evaluador muestra el preferido"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:preferido"}, {"fig": "simbolo", "s": "EV-2.3-2:neutro"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"externo": "El evaluador muestra el objeto neutro"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:neutro"}, {"fig": "simbolo", "s": "EV-2.3-2:preferido"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"externo": "El evaluador muestra el preferido"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:preferido"}, {"fig": "simbolo", "s": "EV-2.3-2:neutro"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"externo": "El evaluador muestra el objeto neutro"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:neutro"}, {"fig": "simbolo", "s": "EV-2.3-2:preferido"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"externo": "El evaluador muestra el preferido"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:preferido"}, {"fig": "simbolo", "s": "EV-2.3-2:neutro"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"externo": "El evaluador muestra el objeto neutro"}, "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:neutro"}, {"fig": "simbolo", "s": "EV-2.3-2:preferido"}]}, {"consigna": "¿Cuál quieres?", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:preferido"}, {"fig": "simbolo", "s": "EV-2.3-2:neutro"}, {"fig": "simbolo", "s": "EV-2.3-2:distractor"}]}, {"consigna": "¿Cuál quieres?", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:preferido"}, {"fig": "simbolo", "s": "EV-2.3-2:neutro"}, {"fig": "simbolo", "s": "EV-2.3-2:distractor"}]}, {"consigna": "¿Cuál quieres?", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:preferido"}, {"fig": "simbolo", "s": "EV-2.3-2:neutro"}, {"fig": "simbolo", "s": "EV-2.3-2:distractor"}]}, {"consigna": "¿Cuál quieres?", "fase": "test", "opciones": [{"fig": "simbolo", "s": "EV-2.3-2:preferido"}, {"fig": "simbolo", "s": "EV-2.3-2:neutro"}, {"fig": "simbolo", "s": "EV-2.3-2:distractor"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-2.3-3', 'item', 2, (select id from dominios_curriculo where codigo = '2.3'), 3, 'Transformación combinatoria', array['tableta']::text[], true, false, 'Solo si EV-2.3-1 obtuvo un 2. Entrenamiento: bloques de 6 ensayos con refuerzo y corrección hasta 5 de 6 en un bloque (máximo 3 bloques o 5 minutos); si no se alcanza, puntuación 0 y no se aplica el test. Test: 6 ensayos sin ayudas ni refuerzo diferencial (solo refuerzo general por colaborar). Se entrena B → C (símbolo como modelo, se elige la palabra). Test: las preguntas de función de EV-2.3-1, solo con las palabras C y el distractor.', 'Los símbolos de EV-2.3-1 (B), 3 palabras inventadas (GAMO, RUPI, SELO) (C) y un distractor.', 3, '3 de 3', '2', '0-1, o no alcanza el criterio de entrenamiento', null, 2, true, '[{"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:coche"}, "opciones": [{"t": "GAMO"}, {"t": "RUPI"}, {"t": "SELO"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:pelota"}, "opciones": [{"t": "RUPI"}, {"t": "GAMO"}, {"t": "SELO"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:sol"}, "opciones": [{"t": "SELO"}, {"t": "GAMO"}, {"t": "RUPI"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:pelota"}, "opciones": [{"t": "RUPI"}, {"t": "GAMO"}, {"t": "SELO"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:sol"}, "opciones": [{"t": "SELO"}, {"t": "GAMO"}, {"t": "RUPI"}]}, {"consigna": "Pon con el que va", "fase": "entrenamiento", "modelo": {"fig": "simbolo", "s": "EV-2.3-1:coche"}, "opciones": [{"t": "GAMO"}, {"t": "RUPI"}, {"t": "SELO"}]}, {"consigna": "¿Cuál sirve para viajar?", "fase": "test", "opciones": [{"t": "GAMO"}, {"t": "RUPI"}, {"t": "SELO"}, {"t": "DUSO"}]}, {"consigna": "¿Cuál sirve para jugar?", "fase": "test", "opciones": [{"t": "RUPI"}, {"t": "GAMO"}, {"t": "SELO"}, {"t": "DUSO"}]}, {"consigna": "¿Cuál sale de día?", "fase": "test", "opciones": [{"t": "SELO"}, {"t": "GAMO"}, {"t": "RUPI"}, {"t": "DUSO"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.1-1', 'item', 3, (select id from dominios_curriculo where codigo = '3.1'), 1, 'Igual o diferente', array['tableta']::text[], false, false, 'Aparecen dos figuras: "¿Son iguales o diferentes?" (botones o respuesta verbal). 4 parejas iguales y 4 diferentes; cada figura aparece en ambos tipos.', '4 figuras abstractas del mismo color, exclusivas de la evaluación.', 8, '7-8 de 8', '6', '5 o menos', null, null, true, '[{"consigna": "¿Son iguales o diferentes?", "correcta": 0, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f1", "v": 2}, {"fig": "abstracta", "s": "EV-3.1-1:f1", "v": 2}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿Son iguales o diferentes?", "correcta": 1, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f1", "v": 2}, {"fig": "abstracta", "s": "EV-3.1-1:f2", "v": 0}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿Son iguales o diferentes?", "correcta": 0, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f3", "v": 1}, {"fig": "abstracta", "s": "EV-3.1-1:f3", "v": 1}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿Son iguales o diferentes?", "correcta": 1, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f3", "v": 1}, {"fig": "abstracta", "s": "EV-3.1-1:f1", "v": 2}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿Son iguales o diferentes?", "correcta": 0, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f2", "v": 0}, {"fig": "abstracta", "s": "EV-3.1-1:f2", "v": 0}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿Son iguales o diferentes?", "correcta": 1, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f4", "v": 2}, {"fig": "abstracta", "s": "EV-3.1-1:f2", "v": 0}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿Son iguales o diferentes?", "correcta": 0, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f4", "v": 2}, {"fig": "abstracta", "s": "EV-3.1-1:f4", "v": 2}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿Son iguales o diferentes?", "correcta": 1, "fase": "test", "modelo": [{"fig": "abstracta", "s": "EV-3.1-1:f2", "v": 0}, {"fig": "abstracta", "s": "EV-3.1-1:f3", "v": 1}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.1-2', 'item', 3, (select id from dominios_curriculo where codigo = '3.1'), 2, 'Distinción mutua', array['tableta']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Se enuncia: "VEKA es diferente de NOLI", "KURA es igual que DOVI", "LIRO es diferente de BOSA". Por cada pareja, una pregunta en el sentido enunciado (control) y otra en el inverso ("¿NOLI es igual o diferente de VEKA?").', 'Tarjetas en pantalla con los nombres VEKA, NOLI, KURA, DOVI, LIRO, BOSA.', 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, '[{"consigna": "VEKA es diferente de NOLI. KURA es igual que DOVI. LIRO es diferente de BOSA.", "fase": "enunciado", "modelo": [{"t": "VEKA"}, {"t": "NOLI"}, {"t": "KURA"}, {"t": "DOVI"}, {"t": "LIRO"}, {"t": "BOSA"}]}, {"consigna": "¿VEKA es igual o diferente de NOLI?", "control": true, "correcta": 1, "fase": "test", "modelo": [{"t": "VEKA"}, {"t": "NOLI"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿DOVI es igual o diferente de KURA?", "correcta": 0, "fase": "test", "modelo": [{"t": "DOVI"}, {"t": "KURA"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿LIRO es igual o diferente de BOSA?", "control": true, "correcta": 1, "fase": "test", "modelo": [{"t": "LIRO"}, {"t": "BOSA"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿NOLI es igual o diferente de VEKA?", "correcta": 1, "fase": "test", "modelo": [{"t": "NOLI"}, {"t": "VEKA"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿KURA es igual o diferente de DOVI?", "control": true, "correcta": 0, "fase": "test", "modelo": [{"t": "KURA"}, {"t": "DOVI"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}, {"consigna": "¿BOSA es igual o diferente de LIRO?", "correcta": 1, "fase": "test", "modelo": [{"t": "BOSA"}, {"t": "LIRO"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.1-3', 'item', 3, (select id from dominios_curriculo where codigo = '3.1'), 3, 'Distinción en redes', array['tableta']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Red 1: "FUMI es diferente de NEPO y NEPO es diferente de RASK" → FUMI–RASK y RASK–FUMI (No se sabe), NEPO–FUMI (control). Red 2: "GULO es igual que PIVO y PIVO es diferente de TOVA" → GULO–TOVA y TOVA–GULO (Diferente), PIVO–GULO (control).', 'Tarjetas en pantalla con los nombres; botones IGUAL, DIFERENTE y NO SE SABE.', 6, '5-6 de 6 con los dos "No se sabe" correctos', '4, o 5-6 fallando algún "No se sabe"', '3 o menos', null, null, true, '[{"consigna": "FUMI es diferente de NEPO y NEPO es diferente de RASK.", "fase": "enunciado", "modelo": [{"t": "FUMI"}, {"t": "NEPO"}, {"t": "RASK"}]}, {"consigna": "¿FUMI es igual o diferente de RASK?", "correcta": 2, "fase": "test", "modelo": [{"t": "FUMI"}, {"t": "RASK"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}, {"t": "No se sabe"}]}, {"consigna": "¿RASK es igual o diferente de FUMI?", "correcta": 2, "fase": "test", "modelo": [{"t": "RASK"}, {"t": "FUMI"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}, {"t": "No se sabe"}]}, {"consigna": "¿NEPO es igual o diferente de FUMI?", "control": true, "correcta": 1, "fase": "test", "modelo": [{"t": "NEPO"}, {"t": "FUMI"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}, {"t": "No se sabe"}]}, {"consigna": "GULO es igual que PIVO y PIVO es diferente de TOVA.", "fase": "enunciado", "modelo": [{"t": "GULO"}, {"t": "PIVO"}, {"t": "TOVA"}]}, {"consigna": "¿GULO es igual o diferente de TOVA?", "correcta": 1, "fase": "test", "modelo": [{"t": "GULO"}, {"t": "TOVA"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}, {"t": "No se sabe"}]}, {"consigna": "¿TOVA es igual o diferente de GULO?", "correcta": 1, "fase": "test", "modelo": [{"t": "TOVA"}, {"t": "GULO"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}, {"t": "No se sabe"}]}, {"consigna": "¿PIVO es igual o diferente de GULO?", "control": true, "correcta": 0, "fase": "test", "modelo": [{"t": "PIVO"}, {"t": "GULO"}], "opciones": [{"t": "Igual"}, {"t": "Diferente"}, {"t": "No se sabe"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.2-1', 'item', 3, (select id from dominios_curriculo where codigo = '3.2'), 1, 'Dame el contrario', array['fisico']::text[], false, false, 'Se muestra un polo: "Dame el contrario de este", con 3 opciones (polo opuesto, copia idéntica y distractor diferente pero no opuesto). Cada par en los dos sentidos.', 'Pares exclusivos de la evaluación: vaso lleno/vacío, toalla mojada/seca, linterna encendida/apagada. Distractores: vaso a medias, toalla de otro color, linterna sin tapa.', 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.2-2', 'item', 3, (select id from dominios_curriculo where codigo = '3.2'), 2, 'Opuestos verbales', array['fisico']::text[], false, false, '"¿Qué es lo contrario de ___?" con limpio/sucio, dormido/despierto y rápido/lento, en los dos sentidos. Respuesta abierta.', null, 6, '5-6 de 6', '3-4', '2 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.2-3', 'item', 3, (select id from dominios_curriculo where codigo = '3.2'), 3, 'Oposición en redes', array['tableta']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Red 1: "WANU es lo contrario de KEMO y KEMO es lo contrario de LOBI" → WANU–LOBI y LOBI–WANU (Igual), KEMO–WANU (control). Red 2: "DUSA es igual que FEP y FEP es lo contrario de BIRA" → DUSA–BIRA y BIRA–DUSA (Contrario), FEP–DUSA (control).', 'Tarjetas en pantalla con los nombres; botones IGUAL y CONTRARIO.', 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, '[{"consigna": "WANU es lo contrario de KEMO y KEMO es lo contrario de LOBI.", "fase": "enunciado", "modelo": [{"t": "WANU"}, {"t": "KEMO"}, {"t": "LOBI"}]}, {"consigna": "¿WANU es igual o contrario que LOBI?", "correcta": 0, "fase": "test", "modelo": [{"t": "WANU"}, {"t": "LOBI"}], "opciones": [{"t": "Igual"}, {"t": "Contrario"}]}, {"consigna": "¿LOBI es igual o contrario que WANU?", "correcta": 0, "fase": "test", "modelo": [{"t": "LOBI"}, {"t": "WANU"}], "opciones": [{"t": "Igual"}, {"t": "Contrario"}]}, {"consigna": "¿KEMO es igual o contrario que WANU?", "control": true, "correcta": 1, "fase": "test", "modelo": [{"t": "KEMO"}, {"t": "WANU"}], "opciones": [{"t": "Igual"}, {"t": "Contrario"}]}, {"consigna": "DUSA es igual que FEP y FEP es lo contrario de BIRA.", "fase": "enunciado", "modelo": [{"t": "DUSA"}, {"t": "FEP"}, {"t": "BIRA"}]}, {"consigna": "¿DUSA es igual o contrario que BIRA?", "correcta": 1, "fase": "test", "modelo": [{"t": "DUSA"}, {"t": "BIRA"}], "opciones": [{"t": "Igual"}, {"t": "Contrario"}]}, {"consigna": "¿BIRA es igual o contrario que DUSA?", "correcta": 1, "fase": "test", "modelo": [{"t": "BIRA"}, {"t": "DUSA"}], "opciones": [{"t": "Igual"}, {"t": "Contrario"}]}, {"consigna": "¿FEP es igual o contrario que DUSA?", "control": true, "correcta": 0, "fase": "test", "modelo": [{"t": "FEP"}, {"t": "DUSA"}], "opciones": [{"t": "Igual"}, {"t": "Contrario"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.2-4', 'item', 3, (select id from dominios_curriculo where codigo = '3.2'), 4, 'Función por oposición', array['tableta']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Se enuncia: "El botón YUBA enciende la música. CORPI es lo contrario de YUBA. NALU es lo contrario de CORPI". Test con CORPI, NALU y TIMU: "Apaga la música" (CORPI) y "Enciende la música" (NALU), dos veces cada una cambiando posiciones. En el test la tableta no reproduce el efecto.', 'Botones dibujados YUBA, CORPI, NALU y distractor TIMU; la tableta puede reproducir música.', 4, '4 de 4', '3', '2 o menos', null, null, true, '[{"consigna": "El botón YUBA enciende la música. CORPI es lo contrario de YUBA. NALU es lo contrario de CORPI.", "fase": "enunciado", "modelo": [{"t": "YUBA"}, {"t": "CORPI"}, {"t": "NALU"}]}, {"consigna": "Apaga la música", "fase": "test", "opciones": [{"t": "CORPI"}, {"t": "NALU"}, {"t": "TIMU"}]}, {"consigna": "Enciende la música", "fase": "test", "opciones": [{"t": "NALU"}, {"t": "CORPI"}, {"t": "TIMU"}]}, {"consigna": "Enciende la música", "fase": "test", "opciones": [{"t": "NALU"}, {"t": "CORPI"}, {"t": "TIMU"}]}, {"consigna": "Apaga la música", "fase": "test", "opciones": [{"t": "CORPI"}, {"t": "NALU"}, {"t": "TIMU"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.3-1', 'item', 3, (select id from dominios_curriculo where codigo = '3.3'), 1, 'Más grande / más pequeño', array['fisico']::text[], false, false, 'Se presentan parejas: "Dame la más grande" / "Dame la más pequeña". En 4 ensayos aparece la mediana, que cambia de papel según la pareja.', '3 cajas idénticas salvo en tamaño (pequeña, mediana, grande), exclusivas de la evaluación.', 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.3-2', 'item', 3, (select id from dominios_curriculo where codigo = '3.3'), 2, 'Ordenar por magnitud', array['fisico']::text[], false, false, '"Ordénalos del más pequeño al más grande", con cada serie.', '4 cilindros de distinta altura y 4 cuerdas de distinta longitud.', 2, 'Las dos series correctas sin ayuda', 'Una serie', 'Ninguna', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.3-3', 'item', 3, (select id from dominios_curriculo where codigo = '3.3'), 3, 'Comparación mutua', array['tableta']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Se enuncia: "TAFO es más grande que MIRU", "BELU es más rápido que KASO", "DORU pesa más que GISA". Por cada pareja, una pregunta en el sentido enunciado (control) y otra en el inverso ("¿Quién es más pequeño?").', 'Personajes dibujados idénticos (ningún rasgo físico indica la relación) con los nombres TAFO, MIRU, BELU, KASO, DORU, GISA.', 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, '[{"consigna": "TAFO es más grande que MIRU.", "fase": "enunciado", "modelo": [{"etiqueta": "TAFO", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "MIRU", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién es más grande?", "control": true, "fase": "test", "opciones": [{"etiqueta": "TAFO", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "MIRU", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién es más pequeño?", "fase": "test", "opciones": [{"etiqueta": "MIRU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "TAFO", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "BELU es más rápido que KASO.", "fase": "enunciado", "modelo": [{"etiqueta": "BELU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "KASO", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién es más rápido?", "control": true, "fase": "test", "opciones": [{"etiqueta": "BELU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "KASO", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién es más lento?", "fase": "test", "opciones": [{"etiqueta": "KASO", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "BELU", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "DORU pesa más que GISA.", "fase": "enunciado", "modelo": [{"etiqueta": "DORU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "GISA", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién pesa más?", "control": true, "fase": "test", "opciones": [{"etiqueta": "DORU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "GISA", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién pesa menos?", "fase": "test", "opciones": [{"etiqueta": "GISA", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "DORU", "fig": "personaje", "s": "EV-3.3:igual"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.3-4', 'item', 3, (select id from dominios_curriculo where codigo = '3.3'), 4, 'Comparación en redes', array['tableta']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Red 1: "HOBE es más grande que JALU y JALU es más grande que KIPE". Red 2: "NAFE es más lento que LIMU y LIMU es más lento que SIBO". En cada red: "¿Quién es el más grande / el más rápido?", "¿KIPE es más grande o más pequeño que HOBE?" (y su equivalente) y una pregunta de control.', 'Personajes dibujados idénticos con los nombres HOBE, JALU, KIPE, NAFE, LIMU, SIBO.', 6, '5-6 de 6', '4', '3 o menos', null, null, true, '[{"consigna": "HOBE es más grande que JALU y JALU es más grande que KIPE.", "fase": "enunciado", "modelo": [{"etiqueta": "HOBE", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "JALU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "KIPE", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién es el más grande?", "fase": "test", "opciones": [{"etiqueta": "HOBE", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "JALU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "KIPE", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿KIPE es más grande o más pequeño que HOBE?", "correcta": 1, "fase": "test", "modelo": [{"etiqueta": "KIPE", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "HOBE", "fig": "personaje", "s": "EV-3.3:igual"}], "opciones": [{"t": "Más grande"}, {"t": "Más pequeño"}]}, {"consigna": "¿Quién es más grande, HOBE o JALU?", "control": true, "fase": "test", "opciones": [{"etiqueta": "HOBE", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "JALU", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "NAFE es más lento que LIMU y LIMU es más lento que SIBO.", "fase": "enunciado", "modelo": [{"etiqueta": "NAFE", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "LIMU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "SIBO", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿Quién es el más rápido?", "fase": "test", "opciones": [{"etiqueta": "SIBO", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "NAFE", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "LIMU", "fig": "personaje", "s": "EV-3.3:igual"}]}, {"consigna": "¿NAFE es más rápido o más lento que SIBO?", "correcta": 1, "fase": "test", "modelo": [{"etiqueta": "NAFE", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "SIBO", "fig": "personaje", "s": "EV-3.3:igual"}], "opciones": [{"t": "Más rápido"}, {"t": "Más lento"}]}, {"consigna": "¿Quién es más lento, LIMU o SIBO?", "control": true, "fase": "test", "opciones": [{"etiqueta": "LIMU", "fig": "personaje", "s": "EV-3.3:igual"}, {"etiqueta": "SIBO", "fig": "personaje", "s": "EV-3.3:igual"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.3-5', 'item', 3, (select id from dominios_curriculo where codigo = '3.3'), 5, 'Valor por comparación', array['fisico']::text[], true, false, 'Se enseña: "Con esta te doy una pegatina" (se canjea una vez) y se enuncia "Esta vale más que esa" y "Esta vale menos que esa". Test sin canje: "¿Cuál prefieres?" en las parejas más–menos (dos posiciones), más–pegatina y pegatina–menos; y 2 ensayos "¿Con cuál compras más?" con 10 y 5 céntimos (la de 5 es más grande).', '3 fichas idénticas diferenciadas solo por un símbolo; pegatinas; monedas de 10 y 5 céntimos.', 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.4-1', 'item', 3, (select id from dominios_curriculo where codigo = '3.4'), 1, 'Claves espaciales', array['fisico']::text[], false, false, '5 receptivos: "Pon el dado encima / debajo / dentro / delante / detrás del vaso". 3 expresivos: el evaluador lo coloca y pregunta "¿Dónde está el dado?".', 'Un dado de goma y un vaso opaco.', 8, '7-8 de 8', '4-6', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.4-2', 'item', 3, (select id from dominios_curriculo where codigo = '3.4'), 2, 'Espaciales mutuas', array['fisico']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Solo verbal: "El gato está encima de la caja", "El libro está delante de la lámpara", "El perro está debajo de la silla". Por cada frase, una pregunta de control y otra inversa ("¿Qué está debajo?").', null, 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.4-3', 'item', 3, (select id from dominios_curriculo where codigo = '3.4'), 3, 'Espaciales en redes', array['fisico']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Red 1: "El libro está encima de la caja y la caja está encima de la mesa" → "¿Qué está más arriba?", "¿El libro está encima o debajo de la mesa?" y una de control. Red 2: igual con delante/detrás (coche, árbol, casa).', null, 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.4-4', 'item', 3, (select id from dominios_curriculo where codigo = '3.4'), 4, 'Búsqueda del tesoro', array['fisico']::text[], false, false, '"La pegatina está dentro de la caja que está detrás de la silla" (3 búsquedas con distintas relaciones y muebles). Solo cuenta la primera elección.', 'Dos cajas idénticas colocadas en posiciones opuestas respecto a un mueble; pegatinas.', 3, '3 de 3', '2', '1 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.5-1', 'item', 3, (select id from dominios_curriculo where codigo = '3.5'), 1, 'Primero / después', array['tableta','fisico']::text[], false, false, 'El evaluador hace dos secuencias de 2 acciones (ej. toca la mesa y aplaude): "¿Qué hice primero? ¿Y después?" (4 ensayos). Después ordena las 2 historias en viñetas (2 ensayos).', '2 historias de 3 viñetas (semilla → riego → flor; huevo → grieta → pollito).', 6, '5-6 de 6', '4', '3 o menos', null, null, true, '[{"consigna": "¿Qué hice primero?", "fase": "test", "modelo": {"externo": "El evaluador hace dos acciones seguidas"}}, {"consigna": "¿Y después?", "fase": "test", "modelo": {"externo": "El evaluador hace dos acciones seguidas"}}, {"consigna": "¿Qué hice primero?", "fase": "test", "modelo": {"externo": "El evaluador hace dos acciones seguidas"}}, {"consigna": "¿Y después?", "fase": "test", "modelo": {"externo": "El evaluador hace dos acciones seguidas"}}, {"consigna": "Ordena la historia", "fase": "test", "opciones": [{"e": "🌱"}, {"e": "💧"}, {"e": "🌷"}], "respuesta": "ordenar"}, {"consigna": "Ordena la historia", "fase": "test", "opciones": [{"e": "🥚"}, {"e": "🐣"}, {"e": "🐥"}], "respuesta": "ordenar"}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.5-2', 'item', 3, (select id from dominios_curriculo where codigo = '3.5'), 2, 'Temporales mutuas', array['fisico']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Tres secuencias inventadas, no rutinas conocidas ("Antes de comer, el mago se pone el sombrero"…). Por cada una, una pregunta de control y otra inversa ("¿Qué hace el mago después de ponerse el sombrero?").', null, 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.5-3', 'item', 3, (select id from dominios_curriculo where codigo = '3.5'), 3, 'Temporales en redes', array['fisico']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Dos redes inventadas ("El pirata canta antes de saltar y salta antes de dormir"): "¿Canta antes o después de dormir?", "¿Qué hace lo último?" y una de control.', null, 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.5-4', 'item', 3, (select id from dominios_curriculo where codigo = '3.5'), 4, 'Instrucciones con orden temporal', array['fisico']::text[], false, false, '4 instrucciones en las que el orden de enunciación no coincide con el de ejecución ("Salta después de tocar la mesa", "Antes de aplaudir, tócate la nariz"…) y 2 en las que coincide ("Da una vuelta y después siéntate").', null, 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.6-1', 'item', 3, (select id from dominios_curriculo where codigo = '3.6'), 1, 'Clasificar con dos criterios', array['fisico']::text[], false, false, '"Pon juntas las que van juntas"; después: "Ahora hazlo de otra manera".', '8 fichas: verdes y naranjas, con forma de estrella y de luna; 2 bandejas.', 2, 'Clasifica y reclasifica con el otro criterio sin ayuda', 'Solo un criterio, o el segundo con ayuda', 'No clasifica', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.6-2', 'item', 3, (select id from dominios_curriculo where codigo = '3.6'), 2, 'Categorías', array['tableta']::text[], false, false, '"Toca todos los animales", "Toca todas las cosas para comer", "Toca todas las cosas amarillas". Correcto si toca todas las que corresponden y ninguna más.', 'Cuadrícula de 12 imágenes con ejemplares nuevos.', 3, '3 de 3', '2', '1 o menos', null, null, true, '[{"consigna": "Toca todos los animales", "correctas": [0, 1, 2, 3], "fase": "test", "opciones": [{"e": "🦉"}, {"e": "🐸"}, {"e": "🦓"}, {"e": "🐤"}, {"e": "🍐"}, {"e": "🥕"}, {"e": "🧀"}, {"e": "🍋"}, {"e": "🚕"}, {"e": "🌼"}, {"e": "🔨"}, {"e": "📘"}], "respuesta": "multiple"}, {"consigna": "Toca todas las cosas para comer", "correctas": [4, 5, 6, 7], "fase": "test", "opciones": [{"e": "🦉"}, {"e": "🐸"}, {"e": "🦓"}, {"e": "🐤"}, {"e": "🍐"}, {"e": "🥕"}, {"e": "🧀"}, {"e": "🍋"}, {"e": "🚕"}, {"e": "🌼"}, {"e": "🔨"}, {"e": "📘"}], "respuesta": "multiple"}, {"consigna": "Toca todas las cosas amarillas", "correctas": [3, 6, 7, 8, 9], "fase": "test", "opciones": [{"e": "🦉"}, {"e": "🐸"}, {"e": "🦓"}, {"e": "🐤"}, {"e": "🍐"}, {"e": "🥕"}, {"e": "🧀"}, {"e": "🍋"}, {"e": "🚕"}, {"e": "🌼"}, {"e": "🔨"}, {"e": "📘"}], "respuesta": "multiple"}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.6-3', 'item', 3, (select id from dominios_curriculo where codigo = '3.6'), 3, 'Jerarquías en redes', array['fisico']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Se enuncia: "Un LIMU es un tipo de pájaro" y "Un TROPI es un tipo de fruta". En cada red: "¿El LIMU es un animal?" (sí), "¿Todos los pájaros son LIMUS?" (no, asimetría), "¿El LIMU es un mueble?" (no, control). Respuesta sí/no.', null, 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.6-4', 'item', 3, (select id from dominios_curriculo where codigo = '3.6'), 4, 'Guárdalo donde va', array['tableta','fisico']::text[], true, false, '"Esto es un CALOPI; es un tipo de juguete. Guárdalo" (y así con una fruta y una prenda inventadas).', 'Dibujos ambiguos de objetos inventados (CALOPI, MURDO, PELSA); frutero, caja de juguetes y armario de ropa (reales o dibujados).', 3, '3 de 3', '2', '1 o menos', null, null, true, '[{"consigna": "Esto es un CALOPI; es un tipo de juguete. Guárdalo.", "fase": "test", "modelo": {"etiqueta": "CALOPI", "fig": "objeto", "s": "EV-3.6-4:CALOPI"}, "opciones": [{"e": "🧸", "etiqueta": "Juguetes"}, {"e": "🍎", "etiqueta": "Frutero"}, {"e": "👕", "etiqueta": "Ropa"}]}, {"consigna": "Esto es un MURDO; es un tipo de fruta. Guárdalo.", "fase": "test", "modelo": {"etiqueta": "MURDO", "fig": "objeto", "s": "EV-3.6-4:MURDO"}, "opciones": [{"e": "🍎", "etiqueta": "Frutero"}, {"e": "🧸", "etiqueta": "Juguetes"}, {"e": "👕", "etiqueta": "Ropa"}]}, {"consigna": "Esto es un PELSA; es un tipo de ropa. Guárdalo.", "fase": "test", "modelo": {"etiqueta": "PELSA", "fig": "objeto", "s": "EV-3.6-4:PELSA"}, "opciones": [{"e": "👕", "etiqueta": "Ropa"}, {"e": "🧸", "etiqueta": "Juguetes"}, {"e": "🍎", "etiqueta": "Frutero"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.7-1', 'item', 3, (select id from dominios_curriculo where codigo = '3.7'), 1, 'Causa y efecto físicos', array['fisico']::text[], false, false, '2 de predicción ("¿Qué pasa si quito este bloque?", "¿Qué va a pasar?" al inclinar el vaso) y 2 de producir el efecto ("Haz que suene", tras verlo una vez).', 'Torre de bloques, vaso con agua, juguete de dos botones en el que solo uno produce sonido.', 4, '4 de 4', '2-3', '1 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.7-2', 'item', 3, (select id from dominios_curriculo where codigo = '3.7'), 2, '¿Por qué? y condicionales', array['fisico']::text[], true, false, '3 preguntas "¿Por qué?" ("¿Por qué abrimos el paraguas?"…). 3 sobre reglas inventadas: "Si digo NOLDA, te tocas la nariz; si digo TRIMA, das una palmada" → "¿Qué haces si digo NOLDA?" (control), "¿Cuándo das una palmada?" y "¿Cuándo te tocas la nariz?" (inversas).', null, 6, '5-6 de 6 con al menos 2 en cada parte', '4, o solo una parte', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.7-3', 'item', 3, (select id from dominios_curriculo where codigo = '3.7'), 3, 'Cadenas causales', array['fisico']::text[], true, false, 'Las relaciones se enuncian (pueden repetirse una vez) y se aplican los ensayos sin ayudas ni refuerzo diferencial. Si falla algún ensayo de control (relación enunciada), la puntuación máxima es 1. Dos cadenas ("Si aprieto el VORNO, se enciende la luz. Si se enciende la luz, el perro se despierta"): "¿Qué pasa si aprieto el VORNO?", "¿Qué tengo que hacer para que el perro se despierte?" y una de control.', null, 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-3.7-4', 'item', 3, (select id from dominios_curriculo where codigo = '3.7'), 4, 'Reglas nuevas y cambio de regla', array['fisico']::text[], false, false, '"Si doy un golpe en la mesa, aplaudes; si doy dos, levantas los brazos" (4 ensayos). "Ahora cambiamos" y se invierte la regla (4 ensayos).', null, 8, '7-8 de 8 con al menos 3 de 4 tras el cambio', '5-6, o solo bien antes del cambio', '4 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.1-1', 'item', 4, (select id from dominios_curriculo where codigo = '4.1'), 1, 'Pronombres y posesivos', array['fisico']::text[], false, false, '"¿Quién está saltando?" (salta el evaluador → "tú"; salta el alumno → "yo"), 2 ensayos. "¿Quién tiene la camiseta azul?", 2. "¿De quién es este zapato?" (mío / tuyo), 2. "Toca mi nariz" / "Toca tu nariz", 2. Repetir el pronombre de la pregunta ("tú" cuando corresponde "yo") es error.', null, 8, '7-8 de 8', '4-6', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.1-2', 'item', 4, (select id from dominios_curriculo where codigo = '4.1'), 2, 'Perspectiva visual', array['fisico']::text[], false, false, 'Tarjeta de dos caras: "¿Qué ves tú?" / "¿Qué veo yo?" (2). Objeto tras una pantalla que solo ve el alumno: "¿Yo puedo ver el coche?" / "¿Y tú?" (2). Frente a frente: "Toca mi mano derecha", "Señala mi pie izquierdo" (2). Antes se pide "Levanta tu mano derecha" (no puntúa): si la falla, esos 2 ensayos no se aplican y la puntuación máxima es 1.', 'Tarjeta con un dibujo distinto en cada cara; pantalla o libro abierto; un coche de juguete.', 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.1-3', 'item', 4, (select id from dominios_curriculo where codigo = '4.1'), 3, 'Emociones propias y de otros', array['fisico','familia']::text[], false, false, 'Propias: "¿Cómo te sientes cuando te dan un regalo / cuando se rompe tu juguete / cuando tienes mucho sueño?" (3). De otros: viñetas por situación ("Se le cae el helado: ¿cómo se siente?") (3).', '3 viñetas en las que no se ve la cara del personaje (de espaldas o lejos).', 6, '5-6 de 6', '4', '3 o menos', '¿Dice cómo se siente (contento, enfadado, cansado, me duele…) sin que se le pregunte?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.1-4', 'item', 4, (select id from dominios_curriculo where codigo = '4.1'), 4, 'Deícticas simples', array['fisico']::text[], false, false, 'YO–TÚ: "Yo tengo un lápiz rojo y tú uno azul. ¿Qué lápiz tengo yo? ¿Y tú?". AQUÍ–ALLÍ: "Yo estoy sentado aquí en la silla y tú allí en el suelo. ¿Dónde estoy yo? ¿Dónde estás tú?". AHORA–ENTONCES: "Ayer comí pasta y hoy como sopa. ¿Qué como ahora? ¿Qué comí ayer?". 2 ensayos por relación.', 'Un lápiz rojo y uno azul.', 6, '5-6 de 6', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.1-5', 'item', 4, (select id from dominios_curriculo where codigo = '4.1'), 5, 'Deícticas invertidas', array['fisico']::text[], false, false, '4 invertidas ("Yo tengo el rojo y tú el azul. Si yo fuera tú y tú fueras yo, ¿qué lápiz tendría yo?"): 2 YO–TÚ, 1 AQUÍ–ALLÍ, 1 AHORA–ENTONCES. 2 simples intercaladas como control frente a responder "siempre lo contrario".', null, 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.1-6', 'item', 4, (select id from dominios_curriculo where codigo = '4.1'), 6, 'Falsa creencia', array['fisico']::text[], false, false, 'Cambio de lugar: "¿Dónde buscará Ana la canica?". Contenido inesperado: "¿Qué pensará tu amigo que hay dentro?". Cada tarea lleva un control de memoria ("¿Dónde la puso al principio?" / "¿Qué pensabas tú que había?") y otro de realidad ("¿Dónde está ahora?" / "¿Qué hay de verdad?"); la tarea solo cuenta si se aciertan los dos controles.', 'Dos muñecos, una cesta, una caja y una canica; una caja de lápices de colores con botones dentro.', 2, 'Las dos tareas', 'Una', 'Ninguna', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.2-1', 'item', 4, (select id from dominios_curriculo where codigo = '4.2'), 1, 'Analogía con pares físicos', array['tableta']::text[], false, false, 'Par modelo igual–igual o diferente–diferente: "¿Cuál se parece a este?", con dos pares de comparación (uno igual y otro diferente) de estímulos distintos a los del modelo. 3 ensayos con modelo igual y 3 con modelo diferente.', 'Pares de figuras exclusivas de la evaluación.', 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, '[{"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f1", "v": 1}, {"fig": "abstracta", "s": "EV-4.2-1:f1", "v": 1}]}, "opciones": [{"par": [{"fig": "abstracta", "s": "EV-4.2-1:f2", "v": 2}, {"fig": "abstracta", "s": "EV-4.2-1:f2", "v": 2}]}, {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f3", "v": 0}, {"fig": "abstracta", "s": "EV-4.2-1:f4", "v": 1}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f7", "v": 1}, {"fig": "abstracta", "s": "EV-4.2-1:f11", "v": 2}]}, "opciones": [{"par": [{"fig": "abstracta", "s": "EV-4.2-1:f9", "v": 0}, {"fig": "abstracta", "s": "EV-4.2-1:f10", "v": 1}]}, {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f8", "v": 2}, {"fig": "abstracta", "s": "EV-4.2-1:f8", "v": 2}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f13", "v": 1}, {"fig": "abstracta", "s": "EV-4.2-1:f13", "v": 1}]}, "opciones": [{"par": [{"fig": "abstracta", "s": "EV-4.2-1:f14", "v": 2}, {"fig": "abstracta", "s": "EV-4.2-1:f14", "v": 2}]}, {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f15", "v": 0}, {"fig": "abstracta", "s": "EV-4.2-1:f16", "v": 1}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f19", "v": 1}, {"fig": "abstracta", "s": "EV-4.2-1:f23", "v": 2}]}, "opciones": [{"par": [{"fig": "abstracta", "s": "EV-4.2-1:f21", "v": 0}, {"fig": "abstracta", "s": "EV-4.2-1:f22", "v": 1}]}, {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f20", "v": 2}, {"fig": "abstracta", "s": "EV-4.2-1:f20", "v": 2}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f25", "v": 1}, {"fig": "abstracta", "s": "EV-4.2-1:f25", "v": 1}]}, "opciones": [{"par": [{"fig": "abstracta", "s": "EV-4.2-1:f26", "v": 2}, {"fig": "abstracta", "s": "EV-4.2-1:f26", "v": 2}]}, {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f27", "v": 0}, {"fig": "abstracta", "s": "EV-4.2-1:f28", "v": 1}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f31", "v": 1}, {"fig": "abstracta", "s": "EV-4.2-1:f35", "v": 2}]}, "opciones": [{"par": [{"fig": "abstracta", "s": "EV-4.2-1:f33", "v": 0}, {"fig": "abstracta", "s": "EV-4.2-1:f34", "v": 1}]}, {"par": [{"fig": "abstracta", "s": "EV-4.2-1:f32", "v": 2}, {"fig": "abstracta", "s": "EV-4.2-1:f32", "v": 2}]}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.2-2', 'item', 4, (select id from dominios_curriculo where codigo = '4.2'), 2, 'Analogías verbales', array['tableta','fisico']::text[], false, false, '"Perro es a cachorro como gato es a…" con 3 opciones: la correcta (gatito), un distractor asociativo (ratón) y otro (perro). 6 analogías.', null, 6, '5-6 de 6', '4', '3 o menos', null, null, true, '[{"consigna": "Perro es a cachorro como gato es a…", "fase": "test", "opciones": [{"t": "gatito"}, {"t": "ratón"}, {"t": "perro"}]}, {"consigna": "Pájaro es a volar como pez es a…", "fase": "test", "opciones": [{"t": "nadar"}, {"t": "agua"}, {"t": "volar"}]}, {"consigna": "Mano es a guante como pie es a…", "fase": "test", "opciones": [{"t": "zapato"}, {"t": "pierna"}, {"t": "mano"}]}, {"consigna": "Día es a sol como noche es a…", "fase": "test", "opciones": [{"t": "luna"}, {"t": "oscuro"}, {"t": "sol"}]}, {"consigna": "Arriba es a abajo como dentro es a…", "fase": "test", "opciones": [{"t": "fuera"}, {"t": "casa"}, {"t": "dentro"}]}, {"consigna": "Libro es a leer como pelota es a…", "fase": "test", "opciones": [{"t": "jugar"}, {"t": "redonda"}, {"t": "leer"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.2-3', 'item', 4, (select id from dominios_curriculo where codigo = '4.2'), 3, 'Equivalencia–equivalencia', array['tableta']::text[], true, false, 'Solo si EV-2.2-1 obtuvo un 2. Si han pasado días, antes 3 ensayos A→C; si falla alguno, no se aplica. Par modelo de la misma clase (BIM–su símbolo) y dos pares de comparación (uno de la misma clase y otro mezclado); después con modelo mezclado. Sin ayudas ni refuerzo diferencial.', 'Las clases formadas en EV-2.2-1 (BIM, LOFA, TUR con sus criaturas y símbolos).', 6, '6 de 6', '5 de 6', '4 o menos', null, 2, true, '[{"consigna": "Toca el BIM", "fase": "comprobacion", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, {"consigna": "Toca el LOFA", "fase": "comprobacion", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, {"consigna": "Toca el TUR", "fase": "comprobacion", "opciones": [{"fig": "simbolo", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}]}, "opciones": [{"par": [{"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}, {"par": [{"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}, "opciones": [{"par": [{"fig": "criatura", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, {"par": [{"fig": "criatura", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "criatura", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, "opciones": [{"par": [{"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}]}, {"par": [{"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, "opciones": [{"par": [{"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}]}, {"par": [{"fig": "criatura", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}]}, "opciones": [{"par": [{"fig": "criatura", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}, {"par": [{"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:BIM"}]}]}, {"consigna": "¿Cuál se parece a este?", "fase": "test", "modelo": {"par": [{"fig": "criatura", "s": "EV-2.2-1:TUR"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}, "opciones": [{"par": [{"fig": "criatura", "s": "EV-2.2-1:BIM"}, {"fig": "simbolo", "s": "EV-2.2-1:TUR"}]}, {"par": [{"fig": "criatura", "s": "EV-2.2-1:LOFA"}, {"fig": "simbolo", "s": "EV-2.2-1:LOFA"}]}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.2-4', 'item', 4, (select id from dominios_curriculo where codigo = '4.2'), 4, 'Metáforas', array['tableta','fisico']::text[], false, false, '"Mi hermano es una tortuga", "Lucía es un león", "Pablo es un terremoto", "Su cuarto es una pocilga": "¿Qué quiere decir?", con 3 opciones (figurado, literal —"tiene caparazón"— y sin relación).', null, 4, '4 de 4', '2-3', '0-1', null, null, true, '[{"consigna": "«Mi hermano es una tortuga» ¿Qué quiere decir?", "fase": "test", "opciones": [{"t": "Que es lento"}, {"t": "Que tiene caparazón"}, {"t": "Que está contento"}]}, {"consigna": "«Lucía es un león» ¿Qué quiere decir?", "fase": "test", "opciones": [{"t": "Que es valiente"}, {"t": "Que tiene melena"}, {"t": "Que tiene sueño"}]}, {"consigna": "«Pablo es un terremoto» ¿Qué quiere decir?", "fase": "test", "opciones": [{"t": "Que es muy movido"}, {"t": "Que hace temblar el suelo"}, {"t": "Que es muy alto"}]}, {"consigna": "«Su cuarto es una pocilga» ¿Qué quiere decir?", "fase": "test", "opciones": [{"t": "Que está muy desordenado"}, {"t": "Que tiene cerdos"}, {"t": "Que es pequeño"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.3-1', 'item', 4, (select id from dominios_curriculo where codigo = '4.3'), 1, 'Peticiones indirectas', array['fisico']::text[], false, false, '4 peticiones indirectas en la situación oportuna ("¿Puedes cerrar la puerta?", "¿Sabes dónde está el lápiz?", "Uf, qué frío entra por esa ventana"…) y 2 preguntas literales de control ("¿Sabes nadar?", "¿Puedes silbar?"), en las que se espera respuesta y no acción.', null, 6, '5-6 de 6 con al menos 3 indirectas', '4', '3 o menos', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.3-2', 'item', 4, (select id from dominios_curriculo where codigo = '4.3'), 2, 'Adaptar el lenguaje', array['fisico','familia']::text[], false, false, 'Par 1: "Explícale cómo se juega al escondite a un niño pequeño (muñeco) y a la directora". Par 2: "Pídeme un lápiz como si yo fuera tu hermano y como si fuera un señor que no conoces".', 'Un muñeco que representa a un niño pequeño.', 2, 'Cambia registro, cortesía o longitud en los dos pares', 'En uno', 'En ninguno', '¿Habla de forma distinta a niños pequeños que a adultos?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.3-3', 'item', 4, (select id from dominios_curriculo where codigo = '4.3'), 3, 'Expresiones hechas', array['fisico']::text[], false, false, '"Estar en las nubes", "tomar el pelo", "costar un ojo de la cara", "echar una mano": explica qué significa o elige entre el significado figurado, uno literal y uno sin relación.', null, 4, '4 de 4', '2-3', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.3-4', 'item', 4, (select id from dominios_curriculo where codigo = '4.3'), 4, 'Refranes', array['fisico']::text[], false, false, '"Más vale tarde que nunca", "Perro ladrador, poco mordedor", "No por mucho madrugar amanece más temprano", "En boca cerrada no entran moscas": elige, entre 3, la situación que encaja con el refrán.', null, 4, '4 de 4', '2-3', '0-1', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.3-5', 'item', 4, (select id from dominios_curriculo where codigo = '4.3'), 5, 'Ironía y bromas', array['tableta','fisico']::text[], false, false, '2 escenas de ironía (se derrama la pintura: "¡Genial, justo lo que necesitaba!"), 1 broma y 1 frase sincera de control: "¿Lo dice de verdad?" y "¿Qué quiere decir?". Para acertar hay que responder bien a las dos.', '4 escenas ilustradas.', 4, '4 de 4', '2-3', '0-1', null, null, true, '[{"consigna": "¿Lo dice de verdad? ¿Qué quiere decir? (correcto solo si acierta las dos)", "fase": "test", "modelo": [{"e": "🎨💦"}, {"t": "«¡Genial, justo lo que necesitaba!»"}], "tipo": "ironia"}, {"consigna": "¿Lo dice de verdad? ¿Qué quiere decir? (correcto solo si acierta las dos)", "fase": "test", "modelo": [{"e": "🌧️"}, {"t": "«¡Qué día tan bueno para ir al parque!»"}], "tipo": "ironia"}, {"consigna": "¿Lo dice de verdad? ¿Qué quiere decir? (correcto solo si acierta las dos)", "fase": "test", "modelo": [{"e": "👴😄"}, {"t": "«¡Te voy a comer a besos!»"}], "tipo": "broma"}, {"consigna": "¿Lo dice de verdad? ¿Qué quiere decir? (correcto solo si acierta las dos)", "control": true, "fase": "test", "modelo": [{"e": "🎁"}, {"t": "«¡Me encanta, gracias!»"}], "tipo": "sincera"}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.4-1', 'item', 4, (select id from dominios_curriculo where codigo = '4.4'), 1, 'Autoinstrucciones', array['fisico','familia']::text[], false, false, '"Antes de empezar, dime qué vas a hacer" (construcción de 4 pasos; se observa si sigue lo que dice). "Si tienes que esperar mucho, ¿qué te puedes decir?". "Si el puzle no te sale, ¿qué te puedes decir?".', 'Bloques y un modelo de construcción de 4 pasos.', 3, '3 de 3 con reglas breves que guían la conducta', '2', '1 o menos', '¿Se habla a sí mismo para organizarse o calmarse ("primero esto", "tranquilo, ya sale")?', null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.4-2', 'item', 4, (select id from dominios_curriculo where codigo = '4.4'), 2, '¿Por qué sigue la regla?', array['tableta','fisico']::text[], false, false, 'Viñetas: "La profe dice ''ponte la chaqueta''. ¿Por qué se la pone Lucas?" → "Para que la profe no se enfade" (pliance) / "Para no tener frío" (tracking). 2 de pliance y 2 de tracking; en una de tracking la consecuencia descrita no se cumple: "¿Qué hará la próxima vez?".', null, 4, '4 de 4', '3', '2 o menos', null, null, true, '[{"consigna": "La profe dice «ponte la chaqueta». Lucas solo se la pone cuando la profe le mira. ¿Por qué se la pone?", "correcta": 0, "fase": "test", "opciones": [{"t": "Para que la profe no se enfade"}, {"t": "Para no tener frío"}]}, {"consigna": "Mamá dice «si riegas la planta, crecerá». Ana la riega todos los días, aunque mamá no esté. ¿Por qué la riega?", "correcta": 1, "fase": "test", "opciones": [{"t": "Para que mamá la vea"}, {"t": "Para que crezca la planta"}]}, {"consigna": "Papá dice «recoge los juguetes». Leo solo los recoge cuando papá está en casa. ¿Por qué los recoge?", "correcta": 0, "fase": "test", "opciones": [{"t": "Para que papá no le riña"}, {"t": "Para encontrarlos luego"}]}, {"consigna": "La caja dice «este juego es muy divertido». Sara lo prueba y se aburre. ¿Qué hará la próxima vez?", "correcta": 1, "fase": "test", "opciones": [{"t": "Volverá a jugar a ese"}, {"t": "Elegirá otro juego"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.4-3', 'item', 4, (select id from dominios_curriculo where codigo = '4.4'), 3, 'Valores', array['fisico']::text[], false, false, '"¿Qué cosas son importantes para ti?", "¿Qué haces que te acerque a eso?" y una elección: "Puedes jugar a la consola o [acción ligada a lo que dijo que le importa]… ¿qué eliges y por qué?".', null, 3, 'Nombra algo que le importa, lo relaciona con una acción concreta y justifica la elección por el valor', 'Solo nombra preferencias (objetos, actividades)', 'No responde o no relaciona', null, null, true, null)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.4-4', 'item', 4, (select id from dominios_curriculo where codigo = '4.4'), 4, 'Pensamientos y hechos', array['tableta','fisico']::text[], false, false, '6 enunciados ("Leo piensa que es tonto", "Leo sacó un 4 en el examen"…): "¿Es un pensamiento o un hecho?".', null, 6, '6 de 6', '5 de 6', '4 o menos', null, null, true, '[{"consigna": "¿Es un pensamiento o un hecho?", "correcta": 0, "fase": "test", "modelo": {"t": "Leo piensa que es tonto"}, "opciones": [{"t": "Pensamiento"}, {"t": "Hecho"}]}, {"consigna": "¿Es un pensamiento o un hecho?", "correcta": 1, "fase": "test", "modelo": {"t": "Marta se sentó sola en el recreo"}, "opciones": [{"t": "Pensamiento"}, {"t": "Hecho"}]}, {"consigna": "¿Es un pensamiento o un hecho?", "correcta": 0, "fase": "test", "modelo": {"t": "Hugo piensa que el perro le va a morder"}, "opciones": [{"t": "Pensamiento"}, {"t": "Hecho"}]}, {"consigna": "¿Es un pensamiento o un hecho?", "correcta": 1, "fase": "test", "modelo": {"t": "Leo sacó un 4 en el examen"}, "opciones": [{"t": "Pensamiento"}, {"t": "Hecho"}]}, {"consigna": "¿Es un pensamiento o un hecho?", "correcta": 0, "fase": "test", "modelo": {"t": "Marta cree que nadie la quiere"}, "opciones": [{"t": "Pensamiento"}, {"t": "Hecho"}]}, {"consigna": "¿Es un pensamiento o un hecho?", "correcta": 1, "fase": "test", "modelo": {"t": "El perro de Hugo ladró"}, "opciones": [{"t": "Pensamiento"}, {"t": "Hecho"}]}]'::jsonb)
insert into evaluacion_items (codigo, tipo, nivel, dominio_id, orden, titulo, formatos, relacional, indicador, consigna, materiales, ensayos, criterio_2, criterio_1, criterio_0, pregunta_familia, requiere_puntuacion, activo, guion) values ('EV-4.4-5', 'item', 4, (select id from dominios_curriculo where codigo = '4.4'), 5, 'El yo que observa', array['fisico']::text[], false, false, '"Cuando eras bebé y ahora, ¿eres la misma persona? ¿Qué ha cambiado y qué sigue igual?". "Ayer estabas enfadado y hoy contento: ¿quién se dio cuenta de las dos cosas?". "Piensa en algo que te preocupa: ¿te puedes dar cuenta de que lo estás pensando?".', null, 3, 'En al menos 2 respuestas distingue un "yo" que se mantiene del contenido que cambia', 'En una', 'En ninguna', null, null, true, null)
